It would look something like this:

```js
import {Transformer} from "@parcel/plugin";
import gql from "graphql";

export default new Transformer({
	async transform({asset}) {
		let code = await asset.getCode();
		let result = gql.parse(code); // <-- not quite sure what need you call here
		asset.setCode(`module.exports = ${JSON.stringify(result)};`);
		return asset;
	}
}
```

and then in your project you need a .parcelrc with
```json5
{
	"extends": "@parcel/config-default"
	"transformers": {
		"*.{gql,graphql}": ["parcel-transformer-graphql-ast"], // <--- your package name
	}
}
```

